  1473	static int read_chunks_after_idat(spng_ctx *ctx)
  1474	{
  1475	    if(ctx == NULL) return 1;
  1476	
  1477	    int ret, discard;
  1478	    int prev_was_idat = 1;
  1479	    struct spng_chunk chunk;
  1480	    unsigned char *data;
  1481	
  1482	    memcpy(&chunk, &ctx->last_idat, sizeof(struct spng_chunk));
  1483	
  1484	    while( !(ret = read_header(ctx, &discard)))
  1485	    {
  1486	        memcpy(&chunk, &ctx->current_chunk, sizeof(struct spng_chunk));
  1487	
  1488	        if(!chunk_fits_in_cache(ctx, &ctx->chunk_cache_usage))
  1489	        { 
  1490	            ret = discard_chunk_bytes(ctx, chunk.length);
  1491	            if(ret) return ret;
  1492	            continue;
  1493	        }
  1494	
  1495	        data = ctx->data;
  1496	
  1497	        ret = read_chunk_bytes(ctx, chunk.length);
  1498	        if(ret) return ret;        
  1499	
  1500	         /* Ignore private chunks */
  1501	        if( (chunk.type[1] & (1 << 5)) != 0) continue;
  1502	
  1503	        /* Critical chunk */
  1504	        if(is_critical_chunk(&chunk))
  1505	        {
  1506	            if(!memcmp(chunk.type, type_iend, 4)) return 0;
  1507	            else if(!memcmp(chunk.type, type_idat, 4) && prev_was_idat) continue; /* ignore extra IDATs */
  1508	            else return SPNG_ECHUNK_POS; /* critical chunk after last IDAT that isn't IEND */
  1509	        }
  1510	
  1511	        prev_was_idat = 0;
  1512	
  1513	        if(!memcmp(chunk.type, type_chrm, 4)) return SPNG_ECHUNK_POS;
  1514	        else if(!memcmp(chunk.type, type_gama, 4)) return SPNG_ECHUNK_POS;
  1515	        else if(!memcmp(chunk.type, type_iccp, 4)) return SPNG_ECHUNK_POS;
  1516	        else if(!memcmp(chunk.type, type_sbit, 4)) return SPNG_ECHUNK_POS;
  1517	        else if(!memcmp(chunk.type, type_srgb, 4)) return SPNG_ECHUNK_POS;
  1518	        else if(!memcmp(chunk.type, type_bkgd, 4)) return SPNG_ECHUNK_POS;
  1519	        else if(!memcmp(chunk.type, type_hist, 4)) return SPNG_ECHUNK_POS;
  1520	        else if(!memcmp(chunk.type, type_trns, 4)) return SPNG_ECHUNK_POS;
  1521	        else if(!memcmp(chunk.type, type_phys, 4)) return SPNG_ECHUNK_POS;
  1522	        else if(!memcmp(chunk.type, type_splt, 4)) return SPNG_ECHUNK_POS;
  1523	        else if(!memcmp(chunk.type, type_offs, 4)) return SPNG_ECHUNK_POS;
  1524	        else if(!memcmp(chunk.type, type_time, 4))
  1525	        {
  1526	           if(ctx->file_time) return SPNG_EDUP_TIME;
  1527	
  1528	           if(chunk.length != 7) return SPNG_ECHUNK_SIZE;
  1529	
  1530	            struct spng_time time;
  1531	
  1532	            time.year = read_u16(data);
  1533	            memcpy(&time.month, data + 2, 1);
  1534	            memcpy(&time.day, data + 3, 1);
  1535	            memcpy(&time.hour, data + 4, 1);
  1536	            memcpy(&time.minute, data + 5, 1);
  1537	            memcpy(&time.second, data + 6, 1);
  1538	
  1539	            if(check_time(&time)) return SPNG_ETIME;
  1540	
  1541	            ctx->file_time = 1;
  1542	
  1543	            if(!ctx->user_time) memcpy(&ctx->time, &time, sizeof(struct spng_time));
  1544	
  1545	            ctx->stored |= SPNG_CHUNK_TIME;
  1546	        }
