  1548	        {
  1549	            if(ctx->file_exif) return SPNG_EDUP_EXIF;
  1550	
  1551	            ctx->file_exif = 1;
  1552	
  1553	            if(!chunk.length) return SPNG_EEXIF;
  1554	
  1555	            struct spng_exif exif;
  1556	
  1557	            exif.data = spng__malloc(ctx, chunk.length);
  1558	            if(exif.data == NULL) return SPNG_EMEM;
  1559	
  1560	            memcpy(exif.data, data, chunk.length);
  1561	            exif.length = chunk.length;
  1562	
  1563	            if(check_exif(&exif))
  1564	            {
  1565	                spng__free(ctx, exif.data);
  1566	                return SPNG_EEXIF;
  1567	            }
  1568	
  1569	            if(!ctx->user_exif) memcpy(&ctx->exif, &exif, sizeof(struct spng_exif));
  1570	            else spng__free(ctx, exif.data);
  1571	
  1572	            ctx->stored |= SPNG_CHUNK_EXIF;
  1573	        }
